package com.zoutrankil.data.repository;

import com.zoutrankil.data.domain.JobDefinitionJson;
import com.zoutrankil.data.domain.MarginAll;
import com.zoutrankil.data.domain.MarginAllDataset;
import com.zoutrankil.data.domain.MarginAllKey;
import com.zoutrankil.data.domain.temporal.TemporalValues;
import com.zoutrankil.data.mapper.MarginAllMapper;
import com.zoutrankil.data.service.StaticTargetIdentity;
import com.zoutrankil.data.service.VerifiedBatchExecutor;
import com.zoutrankil.data.service.MarginAllSource;
import com.zoutrankil.data.service.MarginAllSyncJobOwner;
import io.questdb.client.QuestDB;
import io.questdb.client.Sender;
import org.springframework.jdbc.core.JdbcTemplate;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.Duration;
import java.time.LocalDate;
import java.util.*;

/** Append-only writer for a journal-owned D028 stage; writing directly to non-DEDUP targets is forbidden. */
public final class MarginAllWritePort implements VerifiedBatchExecutor.Port<MarginAll,MarginAllKey> {
    public static final int MAX_BATCH_ROWS=250,MAX_BATCH_BYTES=1024*1024;
    private static final Duration ACK_TIMEOUT=Duration.ofSeconds(10);
    public static final VerifiedBatchExecutor.Codec<MarginAll,MarginAllKey> CODEC=new VerifiedBatchExecutor.Codec<>(){
        @Override public MarginAllKey key(MarginAll row){return row==null?null:row.key();}
        @Override public byte[] canonicalBytes(MarginAll row){try{return JobDefinitionJson.mapper().writeValueAsBytes(new MarginAllMapper().values(row).asMap());}catch(Exception e){throw new IllegalArgumentException("Cannot canonicalize D028 row",e);}}
        @Override public int estimatedTransportBytes(MarginAll row,byte[] canonical){return Math.addExact(Math.multiplyExact(canonical.length,4),128);}};
    private final String formalTable,frozenTargetId;private volatile String writeTable,writeTargetId;private final JdbcTemplate jdbc;private final QuestDB questdb;private final MarginAllMapper mapper=new MarginAllMapper();private volatile boolean senderStopped;
    public MarginAllWritePort(String formalTable,String frozenTargetId,JdbcTemplate jdbc,QuestDB questdb){MarginAllDataset.requireIsolatedTable(formalTable);if(frozenTargetId==null||!frozenTargetId.matches("static-v2-[0-9a-f]{64}"))throw new IllegalArgumentException("Frozen D028 isolated target identity required");this.formalTable=formalTable;this.frozenTargetId=frozenTargetId;writeTable=formalTable;writeTargetId=frozenTargetId;this.jdbc=new JdbcTemplate(Objects.requireNonNull(jdbc).getDataSource());this.jdbc.setQueryTimeout(20);this.jdbc.setMaxRows(MarginAllStorage.MAX_ROWS+1);this.questdb=Objects.requireNonNull(questdb);}
    public synchronized void useStage(String stage,String stageId){MarginAllDataset.requireIsolatedTable(stage);if(!stage.contains("_stage_")||stageId==null||!stageId.matches("static-v2-[0-9a-f]{64}")||stageId.equals(frozenTargetId))throw new IllegalArgumentException("D028 journal-owned stage identity required");writeTable=stage;writeTargetId=stageId;}
    public String formalTable(){return formalTable;}public String stageTable(){return writeTable;}
    @Override public void preflight(){requireWriteTarget();QuestDbWriteChecks.preflight(jdbc,writeTable,MarginAllDataset.isolatedWriteDefinition(writeTable));requireWriteTarget();}
    @Override public void send(List<MarginAll> rows)throws Exception{if(rows==null||rows.isEmpty()||rows.size()>MAX_BATCH_ROWS)throw new IllegalArgumentException("D028 requires 1..250 row batches");if(writeTable.equals(formalTable))throw new IllegalStateException("D028 direct writes forbidden; bind the full-table stage first");preflight();senderStopped=false;DatasetWritePreparation.prepareWalReplace(MarginAllDataset.isolatedWriteDefinition(writeTable),rows,mapper::values,new DatasetWritePreparation.Limits(MAX_BATCH_ROWS,MAX_BATCH_BYTES));long bytes=0;for(var row:rows){bytes=Math.addExact(bytes,CODEC.estimatedTransportBytes(row,CODEC.canonicalBytes(row)));if(bytes>MAX_BATCH_BYTES)throw new IllegalArgumentException("D028 batch exceeds 1 MiB before send");}
        boolean attempted=false;try(Sender sender=questdb.borrowSender()){for(var row:rows){var line=sender.table(writeTable).symbol("exchange_id",row.exchangeId());line.doubleColumn("rzye",row.rzye()).doubleColumn("rzmre",row.rzmre()).doubleColumn("rzche",row.rzche()).doubleColumn("rqye",row.rqye()).doubleColumn("rqmcl",row.rqmcl()).doubleColumn("rzrqye",row.rzrqye()).doubleColumn("rqyl",row.rqyl());line.at(new TemporalValues.CalendarTimestamp(row.tradeDate()).storageCarrier());}long sequence=sender.flushAndGetSequence();attempted=true;if(sequence<0||!sender.awaitAckedFsn(sequence,ACK_TIMEOUT.toMillis()))throw new IllegalStateException("D028 stage ACK unknown; reconcile exact full natural keys before publish");}catch(Exception failure){attempted=true;throw failure;}finally{senderStopped=attempted;}}
    @Override public List<MarginAll> readback(List<MarginAllKey> keys){if(keys==null||keys.isEmpty()||keys.size()>MAX_BATCH_ROWS||new HashSet<>(keys).size()!=keys.size())throw new IllegalArgumentException("D028 readback requires 1..250 unique natural keys");requireWriteTarget();var clauses=new ArrayList<String>();var args=new ArrayList<Object>();for(var key:keys){clauses.add("(trade_date=cast(? AS TIMESTAMP) AND exchange_id=?)");args.add(micros(key.tradeDate()));args.add(key.exchangeId());}var rows=jdbc.query(select(writeTable)+" WHERE "+String.join(" OR ",clauses)+" ORDER BY trade_date,exchange_id LIMIT "+(keys.size()+1),this::physical,args.toArray());if(rows.size()>keys.size())throw new IllegalStateException("D028 duplicate natural key in stage readback");return List.copyOf(rows);}
    public List<MarginAll> readWindow(String table,LocalDate from,LocalDate to){requireBounded(from,to);requireTableIdentity(table);var rows=jdbc.query(select(table)+" WHERE trade_date>=cast(? AS TIMESTAMP) AND trade_date<cast(? AS TIMESTAMP) ORDER BY trade_date,exchange_id LIMIT "+(MarginAllStorage.MAX_ROWS+1),this::physical,micros(from),micros(to.plusDays(1)));if(rows.size()>MarginAllStorage.MAX_ROWS)throw new IllegalStateException("D028 window exceeds 100000 row safety bound");return List.copyOf(rows);}
    public List<MarginAll> readDate(LocalDate date){Objects.requireNonNull(date);requireTableIdentity(formalTable);var rows=jdbc.query(select(formalTable)+" WHERE trade_date=cast(? AS TIMESTAMP) ORDER BY exchange_id LIMIT 4001",this::physical,micros(date));if(rows.size()>MarginAllSource.API_ROW_CAP)throw new IllegalStateException("D028 physical date exceeds source cap");return List.copyOf(rows);}
    public List<LocalDate> readExistingDates(){requireTableIdentity(formalTable);var dates=jdbc.query("SELECT DISTINCT cast(trade_date AS long) AS trade_micros FROM \""+formalTable+"\" ORDER BY trade_micros LIMIT 10001",(rs,n)->date(rs.getLong(1)));if(dates.size()>10000)throw new IllegalStateException("D028 existing-date inventory exceeds 10000 dates");return List.copyOf(dates);}
    public TargetRange readTargetRange(){requireTableIdentity(formalTable);return jdbc.query("SELECT cast(min(trade_date) AS long) AS min_micros,cast(max(trade_date) AS long) AS max_micros,count(*) AS row_count FROM \""+formalTable+"\"",rs->{if(!rs.next())throw new SQLException("D028 target range unavailable");Object min=rs.getObject("min_micros"),max=rs.getObject("max_micros"),count=rs.getObject("row_count");if(!(count instanceof Number n))throw new SQLException("D028 count unavailable");if(min==null&&max==null){if(n.longValue()!=0)throw new SQLException("D028 empty range/count mismatch");return new TargetRange(null,null,0);}if(!(min instanceof Number a)||!(max instanceof Number b)||n.longValue()<1)throw new SQLException("D028 target range invalid");return new TargetRange(date(a.longValue()),date(b.longValue()),n.longValue());});}
    public record TargetRange(LocalDate min,LocalDate max,long rows){public TargetRange{if((min==null)!=(max==null)||min!=null&&min.isAfter(max)||rows<0||(min==null)!=(rows==0))throw new IllegalArgumentException("Invalid D028 range");}public boolean empty(){return rows==0;}}
    @Override public boolean walSettled(){requireWriteTarget();return QuestDbWriteChecks.walSettled(jdbc,writeTable);}@Override public boolean uncertainSenderStopped(){return senderStopped;}
    private MarginAll physical(ResultSet rs,int n)throws SQLException{Object raw=rs.getObject("trade_micros");if(!(raw instanceof Number micros))throw new SQLException("D028 timestamp missing");var v=new LinkedHashMap<String,Object>();v.put("trade_date",date(micros.longValue()));v.put("exchange_id",rs.getString("exchange_id"));for(String f:List.of("rzye","rzmre","rzche","rqye","rqmcl","rzrqye","rqyl")){Object x=rs.getObject(f);if(!(x instanceof Number number)||!Double.isFinite(number.doubleValue()))throw new SQLException("D028 invalid physical value "+f);v.put(f,number.doubleValue());}try{return mapper.fromValues(new com.zoutrankil.data.domain.DatasetValues(v));}catch(RuntimeException e){throw new SQLException("Invalid D028 row",e);}}
    private static String select(String table){return "SELECT cast(trade_date AS long) AS trade_micros,exchange_id,rzye,rzmre,rzche,rqye,rqmcl,rzrqye,rqyl FROM \""+table+"\"";}
    private void requireWriteTarget(){requireTableIdentity(writeTable);}private void requireTableIdentity(String table){var rows=jdbc.queryForList("SELECT id,directoryName FROM tables() WHERE table_name=?",table);if(rows.size()!=1||!(rows.getFirst().get("id") instanceof Number id)||!(rows.getFirst().get("directoryName") instanceof String dir)||!writeTargetId.equals(StaticTargetIdentity.identify(jdbc,table,id.longValue(),dir)))throw new IllegalStateException("D028 physical target generation changed");}
    private static long micros(LocalDate date){return new TemporalValues.CalendarTimestamp(date).storageEpoch(TemporalValues.EpochUnit.MICROS);}private static LocalDate date(long micros){return TemporalValues.CalendarTimestamp.fromStorageEpoch(micros,TemporalValues.EpochUnit.MICROS).date();}
    private static void requireBounded(LocalDate from,LocalDate to){if(from==null||to==null||from.isAfter(to)||java.time.temporal.ChronoUnit.DAYS.between(from,to)+1>MarginAllSyncJobOwner.MAX_WINDOW_DAYS)throw new IllegalArgumentException("D028 bounded date window required");}
}
